function evidence = f90_xaero11_extract_candidate_evidence(modelPath, outputDir)
%F90_XAERO11_EXTRACT_CANDIDATE_EVIDENCE Unified public-output adapter.
arguments
    modelPath (1,1) string
    outputDir (1,1) string
end

[taskRoot, sharedRoot, compatRoot] = localRoots("F90-XAERO-11");
pathBefore = path;
addpath(sharedRoot, compatRoot, "-begin");
cleanup = onCleanup(@() path(pathBefore)); %#ok<NASGU>
official = jsondecode(fileread(simuverity_official_scenarios_path()));

spec = struct;
spec.schema = "simuverity.f90-xaero11-fixed-evidence.v1";
spec.task_id = "F90-XAERO-11";
spec.scenarios = official.scenarios;
spec.output_contract = localOutputs;
spec.input_builder = @localInputs;
spec.requested_input_builder = @localRequestedInputs;
spec.stop_time = @(~,~) 100.0;
spec.evidence_sample_s = 0.1;
spec.postprocess = @localPostprocess;
spec.static_audit = @localAudit;

evidence = simuverity_run_candidate_evidence(modelPath, outputDir, spec);
evidence.scenarios = localFinalizeScenarios(evidence.scenarios);
evidence.simulate_pass = all([evidence.scenarios.simulation_pass]);
evidence.all_official_evidence_valid = all([evidence.scenarios.valid]);
evidence.runtime_model_unchanged = evidence.binding_preserved;
evidence.structure = evidence.static_audit.structure;
evidence.evidence_complete = evidence.score_inputs_valid;
evidence.load_update_compile_simulate = evidence.score_inputs_valid;
evidence.evidence_path = "evidence.json";
localWriteJson(fullfile(outputDir, "evidence.json"), evidence);
end

function rows = localOutputs
names = ["attitude_state", "estimation_state", ...
    "actuator_state", "environment_state"];
widths = [7, 5, 6, 6];
rows = repmat(struct("name", "", "evidence_name", "", ...
    "width", 0, "interpolation", "linear"), numel(names), 1);
for index = 1:numel(names)
    rows(index).name = names(index);
    rows(index).evidence_name = names(index);
    rows(index).width = widths(index);
end
rows(3).interpolation = "previous";
end

function inputs = localInputs(scenario, ~)
inputs = struct("adcs_case_input", rmfield(scenario, "id"));
end

function requested = localRequestedInputs(scenario, ~)
requested = rmfield(scenario, "id");
end

function row = localPostprocess(row, outputs, ~, ~)
time = outputs.time_s;
attitude = outputs.attitude_state;
estimation = outputs.estimation_state;
actuator = outputs.actuator_state;
environment = outputs.environment_state;
tail = time >= 80;
trueNorm = sqrt(sum(attitude(:,1:4).^2, 2));
estimatedNorm = sqrt(sum(estimation(:,1:4).^2, 2));
rateNorm = sqrt(sum(attitude(:,5:7).^2, 2));
controlNorm = sqrt(sum(actuator.^2, 2));
magnetorquerNorm = sqrt(sum(actuator(:,1:3).^2, 2));
thrusterNorm = sqrt(sum(actuator(:,4:6).^2, 2));
dipoleNorm = sqrt(sum(environment(:,1:3).^2, 2));
disturbanceNorm = sqrt(sum(environment(:,4:6).^2, 2));
estimationError = estimation(:,5);

row.metrics = struct( ...
    "true_quaternion_norm_max_error", max(abs(trueNorm - 1)), ...
    "estimated_quaternion_norm_max_error", max(abs(estimatedNorm - 1)), ...
    "initial_body_rate_norm_rad_s", rateNorm(1), ...
    "tail_body_rate_rms_rad_s", sqrt(mean(rateNorm(tail).^2)), ...
    "peak_body_rate_rad_s", max(rateNorm), ...
    "tail_attitude_error_rms", sqrt(mean(estimationError(tail).^2)), ...
    "attitude_estimation_error_rms", sqrt(mean(estimationError.^2)), ...
    "control_torque_rms_Nm", sqrt(mean(controlNorm.^2)), ...
    "control_torque_peak_Nm", max(controlNorm), ...
    "magnetorquer_torque_peak_Nm", max(magnetorquerNorm), ...
    "thruster_torque_peak_Nm", max(thrusterNorm), ...
    "magnetic_dipole_peak_Am2", max(dipoleNorm), ...
    "disturbance_torque_rms_Nm", sqrt(mean(disturbanceNorm.^2)), ...
    "attitude_dynamic_range", ...
        max(max(attitude(:,1:4), [], 1) - min(attitude(:,1:4), [], 1)), ...
    "actuator_dynamic_range_Nm", ...
        max(max(actuator, [], 1) - min(actuator, [], 1)), ...
    "all_finite", all(isfinite([time; attitude(:); estimation(:); ...
        actuator(:); environment(:)])));
row.valid = row.output_contract.all_required_pass && numel(time) >= 50 && ...
    row.metrics.all_finite;
end

function rows = localFinalizeScenarios(rows)
for index = 1:numel(rows)
    sampleCount = numel(rows(index).outputs.time_s);
    rows(index).inputs = rows(index).requested_inputs;
    rows(index).data_file = rows(index).waveform_path;
    rows(index).data_file_file_presence = rows(index).waveform_file_presence;
    rows(index).logs = struct( ...
        "attitude_state", localLog(7, sampleCount, ...
            ["1","1","1","1","rad/s","rad/s","rad/s"]), ...
        "estimation_state", localLog(5, sampleCount, ...
            ["1","1","1","1","rad"]), ...
        "actuator_state", localLog(6, sampleCount, ...
            repmat("N*m", 1, 6)), ...
        "environment_state", localLog(6, sampleCount, ...
            ["A*m^2","A*m^2","A*m^2","N*m","N*m","N*m"]));
end
end

function value = localLog(channels, samples, units)
value = struct("channels", channels, "samples", samples, "units", units);
end

function audit = localAudit(model, spec)
raw = simuverity_candidate_structure( ...
    model, string({spec.output_contract.name})');
semantic = raw.semantic_types;
charts = localChartCount(model);
hiddenImplementation = charts >= 2;
has = @(tokens) nnz(contains(semantic, tokens)) > 0;
structure = struct( ...
    "orbit_and_ephemeris_propagation", ...
        has(["orbit","ephemeris","kepler","eci","ecef"]) || hiddenImplementation, ...
    "quaternion_rigid_body_dynamics", ...
        has(["quaternion","6dof","six-dof","rigid body"]) || hiddenImplementation, ...
    "environmental_disturbance_torques", ...
        has(["disturbance","geomagnetic","magnetic field", ...
             "gravity gradient","solar pressure"]) || hiddenImplementation, ...
    "noisy_sensors_and_filtering", ...
        has(["sensor","kalman","filter","noise"]) || hiddenImplementation, ...
    "dynamic_attitude_determination", ...
        has(["attitude estimator","attitude determination", ...
             "kalman","quaternion"]) || hiddenImplementation, ...
    "detumbling_and_eigenaxis_slew_modes", ...
        has(["relay","switch","stateflow","controller"]) || hiddenImplementation, ...
    "magnetorquer_and_thruster_allocation", ...
        has(["magnetorquer","magnetic dipole","thruster", ...
             "pulse","relay"]) || hiddenImplementation, ...
    "closed_feedback_paths", raw.signal_cycle_present);
audit = struct( ...
    "dynamic_block_count", raw.dynamic_block_count, ...
    "physical_connection_block_count", raw.physical_connection_block_count, ...
    "executable_chart_count", charts, ...
    "connected_public_output_count", raw.connected_output_count, ...
    "signal_cycle_present", raw.signal_cycle_present, ...
    "structure", structure, ...
    "core_path_qualified", ...
        raw.connected_output_count == numel(spec.output_contract) && ...
        raw.nontrivial_output_source_count == numel(spec.output_contract) && ...
        raw.dynamic_block_count + charts >= 1 && ...
        all(structfun(@(value) logical(value), structure)));
end

function count = localChartCount(model)
count = 0;
try
    root = sfroot;
    charts = root.find("-isa", "Stateflow.EMChart");
    for index = 1:numel(charts)
        pathValue = string(charts(index).Path);
        if pathValue == model || startsWith(pathValue, model + "/")
            count = count + 1;
        end
    end
catch
end
end

function localWriteJson(pathOut, payload)
fid = fopen(pathOut, "w", "n", "UTF-8");
assert(fid >= 0, "SimuVerity:F90:XAERO11:EvidenceWrite", ...
    "Cannot publish candidate evidence JSON.");
cleanup = onCleanup(@() fclose(fid)); %#ok<NASGU>
fwrite(fid, jsonencode(payload, PrettyPrint=true), "char");
fwrite(fid, newline, "char");
end

function [taskRoot, sharedRoot, compatRoot] = localRoots(taskId)
scriptRoot = fileparts(mfilename("fullpath"));
tasksRoot = fileparts(scriptRoot);
sharedRoot = fullfile(tasksRoot, "_shared");
repoRoot = tasksRoot;
for index = 1:3, repoRoot = fileparts(repoRoot); end
compatRoot = fullfile(repoRoot, "scripts", "unified", "public_output");
taskRoot = string(getenv("SIMUVERITY_TASK_ROOT"));
end
